// Model-first evolution: users, accounts and transactions as Bun models
// across 100 versions (models100_test.go), every migration generated by
// Migrate (Bun models -> Atlas plan -> goose file), none written by hand.
//
//   - Phase 1 (1-20): tables, foreign keys, columns, simple indexes.
//   - Phase 2 (21-50): unique and composite keys, checks, enums, audit and
//     version columns, splitting a column, money in cents, NOT NULL after a
//     backfill, reviewed drops.
//   - Phase 3 (51-80): partial, expression, GIN, BRIN, hash and covering
//     indexes, replaced checks and indexes.
//   - Phase 4 (81-100): expand and contract, batched backfills, indexes built
//     CONCURRENTLY, enum values, column renames.
//
// Indexes and checks are declared on the models (AfterCreateTable), enums
// before the table (BeforeCreateTable). Data changes are Go data jobs run
// at their version, as a release would ship them.

type m100Version struct {
	v      int
	note   string
	review bool // the generated file drops something and waits for review
	models []any
}

type m100Enum struct {
	name   string
	values []string
}

// m100Enums creates the enum types a model's table uses.
func m100Enums(ctx context.Context, q *bun.CreateTableQuery, enums ...m100Enum) error {
	for _, e := range enums {
		quoted := make([]string, len(e.values))
		for i, v := range e.values {
			quoted[i] = "'" + v + "'"
		}
		_, err := q.DB().ExecContext(ctx, fmt.Sprintf(
			"DO $$ BEGIN CREATE TYPE %s AS ENUM (%s); EXCEPTION WHEN duplicate_object THEN NULL; END $$",
			e.name, strings.Join(quoted, ", ")))
		if err != nil {
			return err
		}
	}
	return nil
}

// m100DDL creates a model's declared indexes and checks.
func m100DDL(ctx context.Context, q *bun.CreateTableQuery, stmts ...string) error {
	for _, stmt := range stmts {
		if _, err := q.DB().ExecContext(ctx, stmt); err != nil {
			return err
		}
	}
	return nil
}

// Data jobs: the data side of a release, in Go, run before (pre) or after
// (post) its migrations. Large ones go in batches of short transactions.

type m100Job func(ctx context.Context, db *bun.DB) error

func m100Update(table, set, where string) m100Job {
	return func(ctx context.Context, db *bun.DB) error {
		_, err := db.NewUpdate().TableExpr(table).Set(set).Where(where).Exec(ctx)
		return err
	}
}

// m100Batched runs an update over id ranges of 10,000 rows, one short
// transaction each, as a backfill on a live table must.
func m100Batched(table, set, where string) m100Job {
	return func(ctx context.Context, db *bun.DB) error {
		var last int64
		if err := db.NewSelect().TableExpr(table).ColumnExpr("coalesce(max(id), 0)").Scan(ctx, &last); err != nil {
			return err
		}
		for lo := int64(0); lo < last; lo += 10_000 {
			_, err := db.NewUpdate().TableExpr(table).Set(set).
				Where("id > ? AND id <= ?", lo, lo+10_000).Where(where).Exec(ctx)
			if err != nil {
				return err
			}
		}
		return nil
	}
}

var (
	m100Pre = map[int]m100Job{
		48: m100Update("transactions", "reference = 'TX' || id", "reference IS NULL"),
		85: m100Batched("accounts", "iban = 'PH' || lpad(id::text, 20, '0')", "iban IS NULL"),
	}
	m100Post = map[int]m100Job{
		17: m100Update("accounts", "opened_at = created_at", "opened_at IS NULL"),
		33: m100Update("users", "first_name = split_part(full_name, ' ', 1), last_name = substr(full_name, length(split_part(full_name, ' ', 1)) + 2)", "first_name IS NULL"),
		36: m100Update("transactions", "amount_cents = round(amount * 100)", "amount_cents IS NULL"),
		39: m100Update("accounts", "balance_cents = round(balance * 100)", "TRUE"),
		82: m100Batched("users", "phone_number = phone", "phone_number IS DISTINCT FROM phone"),
	}
)

func m100Run(ctx context.Context, jobs map[int]m100Job, v int, db *bun.DB) error {
	if job := jobs[v]; job != nil {
		if err := job(ctx, db); err != nil {
			return fmt.Errorf("v%03d data job: %w", v, err)
		}
	}
	return nil
}

// m100History is the 100 versions generated once: the migrations folder,
// the database they were generated on, and how many files existed after
// each version (files[v]).
type m100History struct {
	path  string
	dsn   string
	files []int
	err   error
}

var (
	m100Once   sync.Once
	m100Shared m100History
)

// m100Generated returns the history shared by the tests, generating it on
// first use.
func m100Generated(t testing.TB) *m100History {
	t.Helper()
	requirePG(t)
	m100Once.Do(func() { m100Shared = m100Generate("shared") })
	if m100Shared.err != nil {
		t.Fatalf("generating the 100 versions: %v", m100Shared.err)
	}
	return &m100Shared
}

// m100Generate runs Migrate for every version on a new, empty database and
// folder, approving each reviewed drop, and checks each version converges.
func m100Generate(label string) (h m100History) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Minute)
	defer cancel()
	name := pgRun + "_m100_" + label
	if _, err := admin.ExecContext(ctx, `CREATE DATABASE "`+name+`"`); err != nil {
		return m100History{err: err}
	}
	suiteCleanups = append(suiteCleanups, func() { _, _ = admin.Exec(`DROP DATABASE IF EXISTS "` + name + `" WITH (FORCE)`) })
	path, err := os.MkdirTemp("", "m100-"+label+"-*")
	if err != nil {
		return m100History{err: err}
	}
	suiteCleanups = append(suiteCleanups, func() { _ = os.RemoveAll(path) })
	dir, err := os.Open(path)
	if err != nil {
		return m100History{err: err}
	}
	defer dir.Close()
	h = m100History{path: path, dsn: dsnFor(name), files: []int{0}}
	files := func() []string { m, _ := filepath.Glob(filepath.Join(path, "*")); return m }
	for _, ver := range m100Versions {
		err := func() error {
			s := ecsql.NewSQLService(h.dsn, 2, 4, dir, false, io.Discard, ver.models, nil)
			if err := s.Start(ctx); err != nil {
				return err
			}
			defer s.Stop(context.Background())
			if err := m100Run(ctx, m100Pre, ver.v, s.Client()); err != nil {
				return err
			}
			if err := s.Migrate(ctx); err != nil {
				return err
			}
			review, _ := filepath.Glob(filepath.Join(path, "*"+ecsql.ReviewSuffix))
			if ver.review != (len(review) == 1) || len(review) > 1 {
				return fmt.Errorf("review files %v, want review=%v", review, ver.review)
			}
			if ver.review { // a person read it and approved it
				if err := os.Rename(review[0], strings.TrimSuffix(review[0], ecsql.ReviewSuffix)); err != nil {
					return err
				}
				if err := s.Migrate(ctx); err != nil {
					return fmt.Errorf("after review: %w", err)
				}
			}
			if err := m100Run(ctx, m100Post, ver.v, s.Client()); err != nil {
				return err
			}
			n := len(files())
			if n == h.files[len(h.files)-1] {
				return errors.New("the models changed but no migration was generated")
			}
			if err := s.Migrate(ctx); err != nil || len(files()) != n {
				return fmt.Errorf("does not converge: %w, %d -> %d files", err, n, len(files()))
			}
			h.files = append(h.files, n)
			return nil
		}()
		if err != nil {
			h.err = fmt.Errorf("v%03d (%s): %w", ver.v, ver.note, err)
			return h
		}
	}
	return h
}

// source is the generated folder as an env to copy from.
func (h *m100History) source() *env { return &env{path: h.path} }

// filesOf lists the files version v generated.
func (h *m100History) filesOf(v int) []string {
	all := h.source().files("*.sql")
	return all[h.files[v-1]:h.files[v]]
}

// m100Apply brings a database (with the generated files in its folder)
// from version from to version to, file by file, running each version's
// data jobs, as deploys would. It retries a file that gave up on a lock.
func m100Apply(t testing.TB, h *m100History, s ecsql.ISQLService, from, to int, after func(v int)) {
	t.Helper()
	for v := from + 1; v <= to; v++ {
		if err := m100Run(ctxT(t), m100Pre, v, s.Client()); err != nil {
			t.Fatal(err)
		}
		for range h.files[v] - h.files[v-1] {
			var err error
			for attempt := range 5 {
				if err = s.UpSteps(ctxT(t), 1); err == nil || !retryable(err) {
					break
				}
				time.Sleep(time.Duration(attempt+1) * 200 * time.Millisecond)
			}
			if err != nil {
				t.Fatalf("v%03d (%s): %v", v, m100Versions[v-1].note, err)
			}
		}
		if err := m100Run(ctxT(t), m100Post, v, s.Client()); err != nil {
			t.Fatal(err)
		}
		if after != nil {
			after(v)
		}
	}
}

// m100Env is a new database with the generated files in its folder.
func m100Env(t *testing.T) (*m100History, *env, ecsql.ISQLService) {
	t.Helper()
	h := m100Generated(t)
	e := newEnv(t)
	copyMigrations(t, h.source(), e)
	return h, e, e.started(t)
}

// m100Books checks the money at version v: accounts hold exactly what their
// transactions add up to (and, when exact, what the seed put in).
func m100Books(t testing.TB, s ecsql.ISQLService, v int, exact bool) {
	t.Helper()
	acct, tx := "round(balance * 100)", "round(amount * 100)"
	if v >= 39 {
		acct = "balance_cents"
	}
	if v >= 36 {
		tx = "amount_cents"
	}
	a := sum(t, s, "SELECT coalesce(sum("+acct+"), 0)::bigint FROM accounts")
	b := sum(t, s, "SELECT coalesce(sum("+tx+"), 0)::bigint FROM transactions")
	if a != b || (exact && a != pg100SeedCents) {
		t.Fatalf("v%03d: accounts %d, transactions %d, seeded %d cents", v, a, b, pg100SeedCents)
	}
}

// --- The generation itself ---------------------------------------------------

// Every version's models produce migrations that apply and converge, drops
// wait for review exactly where expected, and nothing is written by hand.
func TestModels100_EveryVersionGeneratesAppliesAndConverges(t *testing.T) {
	t.Parallel()
	h := m100Generated(t)
	for v := 1; v <= 100; v++ {
		for _, f := range h.filesOf(v) {
			if !strings.HasPrefix(readFile(t, f), "-- Generated by Migrate from the models.") {
				t.Errorf("v%03d: %s was not generated", v, filepath.Base(f))
			}
		}
	}
	t.Logf("100 versions generated %d migration files", h.files[100])
}

// The same models generate the same files, byte for byte.
func TestModels100_GenerationIsDeterministic(t *testing.T) {
	t.Parallel()
	a := m100Generated(t)
	b := m100Generate("again")
	if b.err != nil {
		t.Fatal(b.err)
	}
	fa, fb := a.source().files("*.sql"), b.source().files("*.sql")
	if len(fa) != len(fb) {
		t.Fatalf("%d files vs %d", len(fa), len(fb))
	}
	for i := range fa {
		if x, y := readFile(t, fa[i]), readFile(t, fb[i]); x != y {
			t.Fatalf("file %d differs between generations:\n%s\n---\n%s", i, x, y)
		}
	}
}

// --- Determinism and round trip ------------------------------------------------

// A blank database replays the files to exactly the schema the models were
// generated on; every Down restores the schema before its Up, down to
// nothing; climbing again gives the same schema.
func TestModels100_FullRoundTrip(t *testing.T) {
	t.Parallel()
	h := m100Generated(t)
	gen := sql.OpenDB(pgdriver.NewConnector(pgdriver.WithDSN(h.dsn)))
	defer gen.Close()
	want, err := snapshotOf(ctxT(t), bun.NewDB(gen, pgdialect.New()))
	if err != nil {
		t.Fatal(err)
	}
	if got := replayAndRollBack(t, h.source()); got != want {
		t.Fatalf("replaying the files gives another schema than the models:\n%s", diffLines(want, got))
	}
}

// CI drift check: the committed files produce exactly what the final models
// declare, so Migrate on them generates nothing.
func TestModels100_ModelsMatchTheMigrations(t *testing.T) {
	t.Parallel()
	h := m100Generated(t)
	e := newEnv(t)
	copyMigrations(t, h.source(), e)
	s := e.started(t, m100Versions[99].models...)
	if err := s.Migrate(ctxT(t)); err != nil {
		t.Fatal(err)
	}
	if n := len(e.files("*")); n != h.files[100] {
		t.Fatalf("the models drift from the migrations: %d files, want %d", n, h.files[100])
	}
}

// --- Data ----------------------------------------------------------------------

// 100,000 rows per table at v010, then 90 versions over live data with
// their data jobs, the books balanced at every version.
func TestModels100_SeededEvolution(t *testing.T) {
	t.Parallel()
	oneHeavyTest(t)
	h, e, s := m100Env(t)
	m100Apply(t, h, s, 0, 10, nil)
	seed(t, e, pg100SeedSQL)
	m100Apply(t, h, s, 10, 100, func(v int) {
		for _, table := range []string{"users", "accounts", "transactions"} {
			if n := count(t, s, "SELECT count(*) FROM "+table); n != pg100Seed {
				t.Fatalf("v%03d: %s has %d rows", v, table, n)
			}
		}
		m100Books(t, s, v, true)
	})
	for q, want := range map[string]int{
		"SELECT count(*) FROM users WHERE first_name || ' ' || last_name = 'First' || id || ' Last' || id": pg100Seed,
		"SELECT count(*) FROM users WHERE phone_number = '+63917' || lpad(id::text, 7, '0')":               pg100Seed,
		"SELECT count(DISTINCT iban) FROM accounts":                                                        pg100Seed,
		"SELECT count(*) FROM transactions WHERE memo = 'Seed deposit ' || id":                             pg100Seed,
		"SELECT count(*) FROM transactions WHERE kind = 'deposit' AND reference = 'TX' || id":              pg100Seed,
	} {
		if n := count(t, s, q); n != want {
			t.Errorf("v100: %s = %d, want %d", q, n, want)
		}
	}
}

// --- Zero downtime --------------------------------------------------------------

// Versions 51-100 deployed (files and data jobs) while workers hammer all
// three tables: no application query may fail or stall for long.
func TestModels100_ZeroDowntimeUnderLoad(t *testing.T) {
	t.Parallel()
	oneHeavyTest(t)
	h, e, s := m100Env(t)
	m100Apply(t, h, s, 0, 10, nil)
	seed(t, e, pg100SeedSQL)
	m100Apply(t, h, s, 10, 50, nil)

	ctx := ctxT(t)
	var stats loadStats
	stop := make(chan struct{})
	var wg sync.WaitGroup
	for w := range 8 {
		wg.Go(func() { workload(ctx, s, w, stop, &stats) })
	}
	time.Sleep(200 * time.Millisecond)
	before := stats.ops.Load()
	m100Apply(t, h, s, 50, 100, func(v int) { stats.applying.Store(int64(v + 1)) })
	during := stats.ops.Load() - before
	time.Sleep(200 * time.Millisecond)
	close(stop)
	wg.Wait()

	t.Logf("%d operations during versions 51-100, slowest %v", during, time.Duration(stats.slowest.Load()))
	if n := stats.failed.Load(); n > 0 {
		t.Fatalf("%d application operations failed, e.g.:\n%s", n, strings.Join(stats.errs, "\n"))
	}
	if during < 100 {
		t.Fatalf("only %d operations ran during the migrations: traffic stalled", during)
	}
	if slowest := time.Duration(stats.slowest.Load()); slowest > 5*time.Second {
		t.Fatalf("an application operation waited %v behind a migration", slowest)
	}
	m100Books(t, s, 100, false)
}

// The generated late-phase files are shaped for a live database: indexes on
// existing tables are built CONCURRENTLY outside a transaction, and every
// transactional file bounds its lock waits.
func TestModels100_LateMigrationsAreLockSafe(t *testing.T) {
	t.Parallel()
	h := m100Generated(t)
	for v := 51; v <= 100; v++ {
		for _, f := range h.filesOf(v) {
			body := readFile(t, f)
			up, _, _ := strings.Cut(body, "-- +goose Down")
			name := fmt.Sprintf("v%03d %s", v, filepath.Base(f))
			notx := strings.Contains(body, "-- +goose NO TRANSACTION")
			if !notx && !strings.Contains(up, "SET LOCAL lock_timeout") {
				t.Errorf("%s: transactional without lock_timeout", name)
			}
			for _, stmt := range createIndex.FindAllString(up, -1) {
				if !strings.Contains(stmt, "CONCURRENTLY") {
					t.Errorf("%s: %s blocks writes while it builds", name, strings.TrimSpace(stmt))
				}
			}
			if notx && (strings.Contains(up, "ALTER TABLE") || strings.Contains(up, "UPDATE ")) {
				t.Errorf("%s: only concurrent index builds may run outside a transaction", name)
			}
		}
	}
}

// Instances booting together while a CONCURRENTLY build is pending: the ones
// waiting for the migration lock must not hold a snapshot the build waits
// for (they would deadlock through the application, invisibly to Postgres).
func TestModels100_ReplicasBootDuringConcurrentIndexBuilds(t *testing.T) {
	t.Parallel()
	h := m100Generated(t)
	e := newEnv(t)
	copyMigrations(t, h.source(), e)
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	var wg sync.WaitGroup
	for range 6 {
		wg.Go(func() {
			s := ecsql.NewSQLService(e.dsn, 1, 2, e.dir, true, e.out, nil, nil)
			if err := s.Start(ctx); err != nil {
				t.Error(err)
				return
			}
			defer s.Stop(context.Background())
			if err := s.Run(ctx); err != nil {
				t.Error(err)
			}
		})
	}
	wg.Wait()
	s := e.started(t)
	if n := count(t, s, "SELECT count(*) FROM goose_db_version WHERE version_id > 0"); n != h.files[100] {
		t.Fatalf("applied %d of %d migrations", n, h.files[100])
	}
}
